import{d as u,C as t,o as c,c as m,j as a,a as s,E as o,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第五十一章","description":"从道生德畜到生而不有，理解万物成就与不自居其主的玄德。","frontmatter":{"title":"道德经第五十一章","description":"从道生德畜到生而不有，理解万物成就与不自居其主的玄德。","category":"guide","aliases":["道德经第五十一章","老子第五十一章","dao de jing chapter 51"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-51.md","filePath":"daoism/dao-de-jing/chapter-51.md","lastUpdated":1794189804000}'),x={name:"daoism/dao-de-jing/chapter-51.md"},_=u({...x,setup(p){const n=[{id:"conditions-of-completion",label:"道生之，德畜之",showLabel:!0,sentences:[["道生之，",{text:"德",glossary:"de"},{text:"畜",glossary:"xu"},"之，物形之，",{text:"势",glossary:"shi"},"成之。"]],note:["【白话】道使万物发生，德使万物得到蓄养，具体的物质使它们形成形体，所处的条件与态势使它们成就。生、养、成形与完成，各有其所由。","【王弼注择要】「何由而生？道也。何得而畜？德也。何由而形？物也。何使而成？势也。」注逐项追问所由，并说「凡物之所以生，功之所以成，皆有所由」。","【读法】物与势在此说形体的凭借及成就的条件，不直接套作现代物理学模型。德依物之所得解释，不只等于对个人道德品质的评价。"]},{id:"honoring-dao-and-de",label:"尊道而贵德",showLabel:!0,sentences:[["是以万物莫不尊道而贵",{text:"德",glossary:"de"},"。"]],note:["【白话】所以，万物无不以道为尊、以德为贵。它们的发生、蓄养与成就不能离开所由、所得，道德之尊贵由此显出。","【王弼注择要】「道者物之所由也，德者物之所得也。」王弼由万物之所由与所得说明尊道贵德，不先从礼仪上的称颂解释。","【读法】尊与贵在这里连成物之本理解。读者可以将它与前段生养条件相接，不必先想象万物各自作出礼拜行为。"]},{id:"naturally-honored",label:"夫莫之命而常自然",showLabel:!0,sentences:[["道之尊，",{text:"德",glossary:"de"},"之贵，夫莫之",{text:"命",glossary:"ming"},"而常",{text:"自然",glossary:"ziran"},"。"]],note:["【白话】道之所以尊，德之所以贵，并不是谁从外面命定、授予的，而是常常自然而然如此。","【读法】所据注在此附命并作爵的字样，本页沿爵命、授予尊贵的方向解释，不据此扩定另一版本。自然指本然如此，不把道德的尊贵归为某个命令的结果。","【读法】本站保留而字，所据经文在莫之命与常自然之间未见而。此段说明的是道德与万物的关系，不用来证明现实中的任何地位都天然正当。"]},{id:"growth-and-shelter",label:"长之育之",showLabel:!0,sentences:[["故道生之，",{text:"德",glossary:"de"},{text:"畜",glossary:"xu"},"之，",{text:"长",glossary:"zhang"},"之育之，成之",{text:"熟",glossary:"shu"},"之，养之",{text:"覆",glossary:"fu"},"之。"]],note:["【白话】所以，道使之发生，德使之蓄养，使它们成长、发育，成就、成熟，又养护、庇覆它们。这一串动作铺展生养的过程，并非只在最初给予一次。","【王弼注择要】「谓成其实，各得其庇荫，不伤其体矣。」这段注在所据亭之毒之、养之覆之之后，以成实、庇养而不伤其体解释生养之用。","【校读】本站作成之熟之，录文作亭之毒之。前面白话先译本站现文，王注另按其录文的句序说明；不把毒径作现代的毒害义，也不假称两种字面完全相同。"]},{id:"profound-virtue-without-possession",label:"生而不有",showLabel:!0,sentences:[["生而不",{text:"有",glossary:"you"},"，为而不",{text:"恃",glossary:"shi-rely"},"，",{text:"长",glossary:"zhang"},"而不",{text:"宰",glossary:"zai"},"，是谓",{text:"玄德",glossary:"xuande"},"。"]],note:["【白话】使万物发生，却不据为己有；有所作为，却不自恃其功；长养万物，却不把它们置于自己的支配之下。这就叫幽深的玄德。","【王弼注择要】「有德而不知其主也，出乎幽冥，故谓之玄德也。」注以成物而不显一个居功为主者来解释玄德。","【读法】与第十章相参，不有、不恃、不宰都以确有生养之用为前提，不等于放弃照料。所据经注连排录文在为而不恃后又见为而不有，本站未将其增入正文。"]}],r=[{id:"de",term:"德",sense:4},{id:"xu",term:"畜",sense:1},{id:"shi",term:"势",sense:1},{id:"ming",term:"命",sense:1},{id:"ziran",term:"自然",sense:1},{id:"zhang",term:"长",sense:1},{id:"shu",term:"熟",sense:1},{id:"fu",term:"覆",sense:1},{id:"you",term:"有",sense:4},{id:"shi-rely",term:"恃",sense:1},{id:"zai",term:"宰",sense:1},{id:"xuande",term:"玄德",sense:1}];return(b,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十一章",tabindex:"-1"},[s("道德经第五十一章 "),a("a",{class:"header-anchor",href:"#道德经第五十一章","aria-label":'Permalink to "道德经第五十一章"'},"​")],-1)),o(i,{title:"生养万物，为什么又说不有、不恃、不宰",summary:"本章从生、畜、形、成说万物各有所由，再解释道尊德贵的自然，最后将长育、成熟与庇养收于玄德。王弼以道为物之所由、德为物之所得贯通全章，生养之功并不转成占有和支配。",points:[{label:"先读",text:"生、畜、形、成说万物成就的不同条件，畜与长养之长都按动词读。"},{label:"再辨",text:"本站成之熟之与录文亭之毒之分列，先按本站现文翻译，不混用字训。"},{label:"后看",text:"玄德连不有、不恃、不宰理解，帮助成就不必成为据有其功的理由。"}],hint:"畜读 xù，长之与长而不宰的长读 zhǎng，覆读 fù；德在本章连万物所得以蓄养成就来读。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"道生之，德畜之，物形之，势成之。",tone:"各有所由的成就",guide:"把发生、蓄养、成形与成就连起来，不将成物归作单一造作者的功劳。"},{text:"长之育之，成之熟之，养之覆之。",tone:"生养是持续的成全",guide:"先读本站现文，并辨明录文亭之毒之的差异。"},{text:"生而不有，为而不恃，长而不宰，是谓玄德。",tone:"成就而不据有",guide:"生养的作用真实存在，却不转作占有与支配。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=g("",15))])}}});export{y as __pageData,_ as default};
